CREATE TRIGGER UNDGSubstanceJTT_Version_Create
	ON UNDGSubstanceJTT
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT JTT_PK, 'JTT'
	FROM inserted
GO
CREATE TRIGGER UNDGSubstanceJTT_Version_Update
	ON UNDGSubstanceJTT
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON JTT_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
